#!/usr/bin/env bash
# Separate AMD release 1.0.2. The CUDA/telephone installers remain unchanged.
set -Eeuo pipefail
exec python3 - "$0" "$@" <<'AMD_PY_BOOTSTRAP'
import base64, hashlib, io, os, pathlib, sys, tempfile, zipfile
os.umask(0o077)
raw = pathlib.Path(sys.argv[1]).read_bytes().split(b"\n__AMD_PAYLOAD_V1__\n", 1)[1]
data = base64.b64decode(raw, validate=False)
if hashlib.sha256(data).hexdigest() != "792b825516210bc96d682625e58c204f09b70419a54cf3740213d0657f4e6e7d":
    raise SystemExit("AMD-Paketpruefsumme falsch")
with tempfile.TemporaryDirectory(prefix="kienzlefon-amd-") as folder:
    root = pathlib.Path(folder)
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        total = 0
        seen = set()
        for entry in archive.infolist():
            name = pathlib.PurePosixPath(entry.filename)
            total += entry.file_size
            if (name.is_absolute() or ".." in name.parts or entry.filename in seen
                or entry.is_dir() or total > 20000000):
                raise SystemExit("Unsicheres AMD-Paket")
            seen.add(entry.filename)
            target = root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(entry))
    sys.path.insert(0, str(root))
    import installer
    try:
        raise SystemExit(installer.main(sys.argv[2:]))
    except installer.Failure as error:
        print("FEHLER: " + str(error), file=sys.stderr)
        raise SystemExit(1)
    except KeyboardInterrupt:
        print("AMD-Vorgang abgebrochen", file=sys.stderr)
        raise SystemExit(130)
    except Exception:
        print("AMD-Vorgang fehlgeschlagen; vertrauliche Details unterdrueckt", file=sys.stderr)
        raise SystemExit(1)
AMD_PY_BOOTSTRAP
exit 0
